 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find distinct nonzero color sequences repeated across three adjacent rows
    # or columns: this stripe is the ordered recoloring palette.
    palettes = []
    for r in range(h - 2):
        for c in range(w):
            for n in range(3, w - c + 1):
                seq = [grid[r][c + j] for j in range(n)]
                if all(seq) and len(set(seq)) == n and all(
                    grid[r + k][c:c+n] == seq for k in (1, 2)
                ):
                    palettes.append(seq)
    for r in range(h):
        for c in range(w - 2):
            for n in range(3, h - r + 1):
                seq = [grid[r + j][c] for j in range(n)]
                if all(seq) and len(set(seq)) == n and all(
                    [grid[r + j][c + k] for j in range(n)] == seq for k in (1, 2)
                ):
                    palettes.append(seq)
    if not palettes:
        raise ValueError('palette stripe not found')
    palette = max(palettes, key=len)

    # Extract connected components of color 1; the largest is the template
    # motif (a small color-1 swatch may also occur in the palette strip).
    remaining = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1}
    components = []
    while remaining:
        start = remaining.pop()
        comp = {start}
        stack = [start]
        while stack:
            r, c = stack.pop()
            for dr in (-1, 0, 1):
                for dc in (-1, 0, 1):
                    p = (r + dr, c + dc)
                    if p in remaining:
                        remaining.remove(p)
                        comp.add(p)
                        stack.append(p)
        components.append(comp)
    motif = max(components, key=len)
    r0 = min(r for r, c in motif)
    c0 = min(c for r, c in motif)
    shape = {(r-r0, c-c0) for r, c in motif}
    height = max(r for r, c in shape) + 1
    anchor = palette.index(1)

    out = [[0] * w for _ in range(h)]
    for i, color in enumerate(palette):
        top = r0 + (i-anchor) * height
        for dr, dc in shape:
            r, c = top + dr, c0 + dc
            if 0 <= r < h and 0 <= c < w:
                out[r][c] = color
    return out

